function Preferences({preferences,update,onReset}:{preferences?:FlowPreferences;update:(p:Partial<FlowPreferences>)=>Promise<void>;onReset?:()=>void}){const save=(p:Partial<FlowPreferences>)=>void update(p).catch(()=>undefined);return <div className="space-y-3"><Preference label="Suggerimenti di Flow" description="Mostra indicazioni contestuali mentre lavori." checked={preferences?.suggestionsEnabled??true} onChange={x=>save({suggestionsEnabled:x})}/><Preference label="Stati vuoti illustrati" description="Usa illustrazioni pertinenti quando non ci sono record." checked={preferences?.illustratedEmptyStates??true} onChange={x=>save({illustratedEmptyStates:x})}/><Preference label="Animazioni" description="Attiva transizioni leggere." checked={preferences?.animationsEnabled??true} onChange={x=>save({animationsEnabled:x})}/><Preference label="Riduci movimento" description="Limita movimenti non essenziali." checked={preferences?.reducedMotion??false} onChange={x=>save({reducedMotion:x})}/><Preference label="Assistenza contestuale" description="Mostra Flow soltanto nei momenti utili." checked={preferences?.contextualMascotEnabled??true} onChange={x=>save({contextualMascotEnabled:x})}/><div className="border-t pt-4"><p className="text-sm font-semibold">Ripristino</p><div className="mt-2 grid gap-2"><Button variant="outline" onClick={()=>save({dismissedModules:[]})}>Ripristina suggerimenti</Button><Button variant="outline" className="text-destructive" onClick={onReset}>Azzera progresso tutorial</Button></div></div></div>}
export function useFlowExperience(){const value=useContext(FlowContext);if(!value)throw new Error("useFlowExperience deve essere usato dentro FlowExperienceProvider");return value}
export function FlowHelpButton(){const flow=useFlowExperience();return <Button variant="ghost" className="w-full justify-start" onClick={flow.openHelp} data-flow-tour="flow-help"><CircleHelp/><span>Aiuto e tutorial</span></Button>}
export function FlowSettingsPanel(){const flow=useFlowExperience();return <Card className="p-4"><h3 className="font-semibold">Aspetto e assistenza</h3><p className="mb-4 text-xs text-muted-foreground">Personalizza la guida Flow.</p><Preferences preferences={flow.preferences} update={flow.update}/><Button className="mt-4 w-full" onClick={()=>flow.startTour(MAIN)}>Impara il flusso DoFlow</Button></Card>}
